const environment = import.meta.env;

export function formatID(input: string) {
  input = input.replace(/-/g, '');

  if (input.length > 3) {
    input = input.slice(0, 3) + '-' + input.slice(3);
  }

  if (input.length > 13) {
    input = input.slice(0, 13) + '-' + input.slice(13);
  }

  return input;
}

export const parseToMoney = (value: any) => {
  if (!value) return Number(0).toFixed(2);
  if (isNaN(value)) return null;

  return Number(value).toLocaleString(undefined, {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
};

export function env() {
  return {
    THIRDPARTY_SERVICES: environment.VITE_THIRDPARTY_SERVICES,
    DASHBOARD_API_URL: environment.VITE_DASHBOARD_API_URL,
    ENVIRONMENT: environment.VITE_ENVIRONMENT,
    SENTINEL_API: environment.VITE_SENTINEL_API,
    AUTH0_DOMAIN: environment.VITE_AUTH0_DOMAIN,
    AUTH0_CLIENTID: environment.VITE_AUTH0_CLIENTID,
  };
}

export function initials(value = '') {
  const valueArray = value?.split(' ');

  return valueArray.map(([first]) => first?.toUpperCase()).join('');
}

